      "@type": "FAQPage",
      "@id": "https://www.data4thepeople.com/p/rentals-within-reach#faq",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "What does \"within reach\" mean?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "A rental counts as within reach when its monthly rent, including utilities, is at or under what the household can pay. The tool sets that ceiling at 30% of the household’s yearly income, divided by 12. You can change the 30%."
          }
        },
        {
          "@type": "Question",
          "name": "How many rentals can the median renter afford?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "In 1,960 of 3,141 counties, the median renter household can afford fewer than half the rentals in its own county. That is for 2020-2024, at 30% of income after taxes. Counted before taxes, it is 1,084 of 3,141 counties."
          }
        },
        {
          "@type": "Question",
          "name": "Does the map show apartments available to rent now?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. It counts rentals that people live in now, by what the current tenant pays. A unit rented at a low price for many years counts the same as one on the market today, so the share a new renter can find is very likely lower."
          }
        },
        {
          "@type": "Question",
          "name": "Can I enter my own income, and is it saved?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes, choose “Enter an income” under Household Income and type a yearly figure. Nothing you enter is saved or sent anywhere. The calculation runs in your browser."
          }
        },
        {
          "@type": "Question",
          "name": "Why does it use income after taxes?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Rent is paid from take-home pay, so the tool starts there. It subtracts federal and state income tax and payroll tax for one wage earner. This is stricter than the usual 30% rule, which uses income before taxes. Switch to “Before taxes” to see that version."
          }
        },
        {
          "@type": "Question",
          "name": "How do I find my county?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Type its name in “Find a county”, or pick your state under “Show one state” and click its bubble. The panel on the right shows the rent ceiling, the county’s rentals by monthly rent, and how its rentals have changed since 2005-2009."
          }
        },
        {
          "@type": "Question",
          "name": "Why are there only four time periods?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "County figures come from 5-year surveys. The four periods shown (2005-2009, 2010-2014, 2015-2019 and 2020-2024) do not overlap, so each change on the map compares two separate sets of survey responses."
          }
        },
        {
          "@type": "Question",
          "name": "Where does the data come from?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Rents and incomes are from the U.S. Census Bureau’s American Community Survey 5-year estimates. Taxes are estimated with the NBER TAXSIM model and Social Security Administration payroll tax rates. The method and its limits are on GitHub."
          }
        }
